export const metadata = { title: "Organization" };

const snapshotSchema=z.object({id:z.uuid(),version:z.number().int().nonnegative(),description:z.string(),posted_on:z.iso.date(),amount_minor:z.string().regex(/^-?\d+$/),currency_code:z.string().regex(/^[A-Z]{3}$/),merchant_id:z.uuid().nullable(),category_id:z.uuid().nullable()}).passthrough();
export default async function OrganizationPage({searchParams}:{searchParams:Promise<Record<string,string|string[]|undefined>>}) {
 const {supabase,workspace}=await requireWorkspace();const params=await searchParams;
 const requestedReview=z.uuid().safeParse(params.review);
 const reviewId=requestedReview.success?requestedReview.data:null;
 let invalidLink=params.review!==undefined&&!requestedReview.success;
 const requestedImport=z.uuid().safeParse(params.import);
 const importId=requestedImport.success?requestedImport.data:null;
 if(params.import!==undefined&&!requestedImport.success)invalidLink=true;
 let cursor:{date:string;id:string}|null=null;
 if(params.cursor){const parts=String(params.cursor).split(':');const date=z.iso.date().safeParse(parts[0]),id=z.uuid().safeParse(parts[1]);if(parts.length===2&&date.success&&id.success)cursor={date:date.data,id:id.data};else invalidLink=true;}
 let query=supabase.from('transactions').select(importId?'id,version,posted_on,transaction_sources!inner(source_transactions!inner(import_id))':'id,version,posted_on',{count:'exact'}).eq('workspace_id',workspace.id).neq('status','voided').neq('kind','transfer');
 query=query.or(cursor?`and(or(merchant_id.is.null,category_id.is.null),or(posted_on.lt.${cursor.date},and(posted_on.eq.${cursor.date},id.lt.${cursor.id})))`:'merchant_id.is.null,category_id.is.null');
 if(importId)query=query.eq('transaction_sources.source_transactions.import_id',importId);
 const loans=await loadLoanPayoutIds(supabase,workspace.id).catch(()=>new Set<string>());
 if(loans.size)query=query.not('id','in',`(${[...loans].join(',')})`);
 const [queue,merchants,categories,rules,reviews,selectedReview]=await Promise.all([
  query.order('posted_on',{ascending:false}).order('id',{ascending:false}).limit(51),
  supabase.from('merchants').select('id,name').eq('workspace_id',workspace.id).order('name').limit(501),
  supabase.from('categories').select('id,name').eq('workspace_id',workspace.id).order('name').limit(501),
  supabase.from('organization_rules').select('id,description_key,merchant_id,category_id,enabled,version').eq('workspace_id',workspace.id).order('description_key').limit(MAX_ORGANIZATION_RULES+1),
  supabase.from('organization_reviews').select('id,status,created_at').eq('workspace_id',workspace.id).order('created_at',{ascending:false}).order('id',{ascending:false}).limit(10),
  reviewId?supabase.from('organization_reviews').select('*').eq('workspace_id',workspace.id).eq('id',reviewId).maybeSingle():{data:null,error:null},
 ]);
 if(queue.error||merchants.error||categories.error||rules.error||reviews.error||selectedReview.error)throw queue.error??merchants.error??categories.error??rules.error??reviews.error??selectedReview.error;
 const queueRows=z.array(z.object({id:z.uuid(),version:z.number().int().nonnegative(),posted_on:z.iso.date()})).parse(queue.data);
 if(merchants.data.length>500||categories.data.length>500||rules.data.length>MAX_ORGANIZATION_RULES)throw new Error('Organization target coverage exceeded; use Transactions for manual correction');
 const queueTotal=queue.count??queueRows.length;
 const selected=queueRows.slice(0,50).map(({id,version})=>({id,version}));
 const suggestions=selected.length?await loadOrganizationSuggestions(supabase,workspace.id,selected):null;
 const items=(suggestions?.proposals??[]).map(proposal=>({proposal,row:suggestions!.rows.find(row=>row.id===proposal.transactionId)!}));
 const review=selectedReview.data;
 const snapshots=review?z.array(snapshotSchema).max(50).parse(review.snapshots):[];
 const [batch,currentRows]=await Promise.all([
  review?.batch_id?supabase.from('transaction_batches').select('undone').eq('workspace_id',workspace.id).eq('id',review.batch_id).maybeSingle():{data:null,error:null},
  review?.batch_id?supabase.from('transactions').select('id,version').eq('workspace_id',workspace.id).in('id',snapshots.map(row=>row.id)):{data:[],error:null},
 ]);
 if(batch.error||currentRows.error)throw batch.error??currentRows.error;
 const merchantName=(id:unknown)=>id?merchants.data.find(row=>row.id===id)?.name??'a removed merchant':null;
 const categoryName=(id:unknown)=>id?categories.data.find(row=>row.id===id)?.name??'a removed category':null;
 const reviewStatus:Record<string,string>={pending:'Waiting for approval',applied:'Applied',dismissed:'Dismissed'};
 const totals:Record<string,string>={};for(const row of snapshots)totals[row.currency_code]=(BigInt(totals[row.currency_code]??'0')+BigInt(row.amount_minor)).toString();
 const last=queueRows[49],next=queueRows.length>50&&last?new URLSearchParams({...importId?{import:importId}:{},cursor:last.posted_on+':'+last.id}).toString():null;
 const patchMerchant=review?(review.merchant_name??(Object.hasOwn(review.patch,'merchant_id')?merchantName(review.patch.merchant_id)??'no merchant':undefined)):undefined;
 const patchCategory=review&&Object.hasOwn(review.patch,'category_id')?categoryName(review.patch.category_id)??'uncategorized':undefined;
 const card='rounded-xl border border-border bg-card p-6';
 const ruleItem=(rule:typeof rules.data[number])=><li key={rule.id} className="flex flex-wrap items-center justify-between gap-2 py-2"><span className={rule.enabled?'':'text-muted-foreground'}><span className="font-medium" title={rule.description_key}>{merchantName(rule.merchant_id)??organizationDisplayName(rule.description_key)}</span> → {categoryName(rule.category_id)??'no category'}</span><SafeForm action={toggleRuleSafely}><input type="hidden" name="key" value={rule.description_key} /><input type="hidden" name="merchant" value={rule.merchant_id??''} /><input type="hidden" name="category" value={rule.category_id??''} /><input type="hidden" name="version" value={rule.version} /><input type="hidden" name="enabled" value={String(!rule.enabled)} /><button aria-label={(rule.enabled?'Disable':'Enable')+' rule for '+(merchantName(rule.merchant_id)??organizationDisplayName(rule.description_key))} className="min-h-6 text-xs underline">{rule.enabled?'Disable':'Enable'}</button></SafeForm></li>;
 return <main className="mx-auto w-full max-w-[1400px] space-y-6 px-4 py-6 text-foreground sm:px-8 lg:py-8">
  {invalidLink&&<p role="alert" className="text-sm">That link is out of date, so this is the start of your queue.</p>}
  <header><p className="eyebrow">Money</p><h1 className="mt-1 page-title">Organize transactions</h1>
   <p className="mt-2 text-sm text-muted-foreground">Tick entries, pick a category, press Apply. Each batch stays in history, and you can undo it unless a later edit conflicts.</p></header>
  {reviewId&&!review&&<p role="alert" className="text-sm">This review is no longer available.</p>}
  {review&&<section aria-label="Organization impact preview" className={card}>
   <h2 className="text-sm font-medium">{batch.data?.undone?'Undone':review.status==='applied'?'Applied':review.status==='dismissed'?'Dismissed':'Not applied yet'}{patchCategory&&` · ${patchCategory}`}{patchMerchant&&` · ${patchMerchant}`}</h2>
   <details className="mt-1 text-sm"><summary className="cursor-pointer text-muted-foreground hover:text-foreground">{snapshots.length} {snapshots.length===1?'entry':'entries'} · Total {Object.entries(totals).map(([currency,minor])=>formatMoney(minor,currency,workspace.locale)).join('; ')}</summary>
   <ul className="mt-3 divide-y divide-border text-sm">{snapshots.map(row=>{
    const beforeMerchant=merchantName(row.merchant_id)??'unassigned';
    const beforeCategory=categoryName(row.category_id)??'uncategorized';
    return <li key={row.id} className="flex flex-wrap items-baseline gap-x-3 py-2"><span className="font-mono text-xs text-muted-foreground">{row.posted_on}</span><Link className="min-w-0 flex-1 truncate hover:underline" href={'/money/transactions?transaction='+row.id}>{row.description}</Link><span className="font-mono">{formatMoney(row.amount_minor,row.currency_code,workspace.locale)}</span>
     <span className="basis-full text-xs text-muted-foreground">{`Merchant: ${beforeMerchant} → ${patchMerchant??beforeMerchant}`} · {`Category: ${beforeCategory} → ${patchCategory??beforeCategory}`}</span></li>;
   })}</ul></details>
   {review.status==='pending'&&<><ApprovalForm reviewId={review.id} canSaveRule={Boolean(review.rule_key)} /><SafeForm action={dismissReviewSafely} className="mt-3"><input type="hidden" name="reviewId" value={review.id} /><button className="text-sm text-muted-foreground underline">Dismiss</button></SafeForm></>}
   {review.status==='applied'&&review.rule_key&&<p className="mt-2 text-sm text-muted-foreground">{rules.data.some(rule=>rule.enabled&&rule.description_key===review.rule_key)?'A rule suggests the same for future entries with this description.':'No rule was saved for future entries.'}</p>}
   {review.batch_id&&!batch.data?.undone&&(currentRows.data.length===snapshots.length?<UndoReviewForm reviewId={review.id} rows={versionedRows.parse(currentRows.data)} />:<p className="mt-3 text-sm text-muted-foreground">Undo isn’t available: {snapshots.length-currentRows.data.length} of these entries no longer exist. The history above is kept; correct the rest in <Link className="underline" href="/money/transactions">Transactions</Link>.</p>)}
  </section>}
  <section aria-label="Organization suggestions" className="space-y-3">
   <h2 className="text-sm font-medium">{items.length?`${queueTotal} ${cursor?'older ':''}${queueTotal===1?'entry':'entries'} to organize${queueTotal>items.length?`, showing ${items.length}`:''}`:queueRows.length?`${queueTotal} ${queueTotal===1?'entry needs':'entries need'} organizing, with no suggestion yet`:importId?'Nothing left to organize in this import':cursor?'No older entries to organize':'Everything is organized'}</h2>
   {!items.length&&queueRows.length>0&&<p className="text-sm text-muted-foreground">Set their category or merchant in <Link className="underline" href="/money/transactions?category=none">Transactions</Link>.</p>}
   {items.length>0&&<OrganizationQueue key={items.map(item=>item.row.id+':'+item.row.version).join(',')} items={items} merchants={merchants.data} categories={categories.data} requestId={crypto.randomUUID()} locale={workspace.locale} />}
   <div className="flex flex-wrap gap-4 text-sm">{cursor&&<Link className="underline" href={'/money/organization'+(importId?'?import='+importId:'')}>Newest entries</Link>}{next&&<Link className="underline" href={'/money/organization?'+next}>Older entries</Link>}</div>
   <p className="text-xs text-muted-foreground">Newest first. Suggestions compare up to 2,000 recent posted entries and 2,000 rules. For one-off fixes use <Link className="underline" href="/money/transactions">Manual correction in Transactions</Link>.</p>
  </section>
  <details className={card}><summary className="cursor-pointer text-sm font-medium">Rules ({rules.data.filter(rule=>rule.enabled).length}) and recent reviews</summary>
   <ul className="mt-3 divide-y divide-border text-sm">{rules.data.filter(rule=>rule.enabled).map(ruleItem)}</ul>
   {rules.data.some(rule=>!rule.enabled)&&<details className="mt-2"><summary className="cursor-pointer text-sm text-muted-foreground">Disabled ({rules.data.filter(rule=>!rule.enabled).length})</summary>
    <ul className="mt-2 divide-y divide-border text-sm">{rules.data.filter(rule=>!rule.enabled).map(ruleItem)}</ul></details>}
   {!rules.data.length&&<p className="mt-2 text-sm text-muted-foreground">No rules yet.</p>}
   <ul className="mt-3 space-y-1 border-t border-border pt-3 text-sm">{reviews.data.map(row=><li key={row.id}><Link className="underline" href={'/money/organization?review='+row.id}>{reviewStatus[row.status]??row.status} · {new Date(row.created_at).toLocaleString(workspace.locale,{timeZone:workspace.timezone})}</Link></li>)}</ul>
   {!reviews.data.length&&<p className="mt-2 text-sm text-muted-foreground">No reviews yet.</p>}
  </details>
 </main>;
}
'use client';
import { Fragment,useActionState,useEffect,useRef,useState} from 'react';
import {createReview,applyReview,undoReview} from './actions';
import {formatMoney} from '@/lib/finance/format';
import type {OrganizationProposal} from '@/lib/import/organization';

type Row={id:string;version:number;description:string;posted_on:string;amount_minor:string;currency_code:string};
type Target={id:string;name:string};
type Item={row:Row;proposal:OrganizationProposal};
const field='min-h-10 rounded-lg border border-border bg-card px-3 py-2 text-sm text-foreground';
function choice(targets:Target[],name:string):[string,string]{
 const trimmed=name.trim();if(!trimmed)return ['keep',''];
 const found=targets.find(target=>target.name.toLowerCase()===trimmed.toLowerCase());
 return found?[found.id,'']:['new',trimmed];
}
export function groupedByDescription<T extends { row: { description: string; posted_on: string } }>(items: T[]) {
  const groups = new Map<string, T[]>();
  for (const item of items) { const key = item.row.description.trim().toLocaleLowerCase("en"); groups.set(key, [...(groups.get(key) ?? []), item]); }
  return [...groups.values()].map(group => [...group].sort((a, b) => b.row.posted_on.localeCompare(a.row.posted_on)));
}

export function OrganizationQueue({items,merchants,categories,requestId,locale}:{items:Item[];merchants:Target[];categories:Target[];requestId:string;locale:string}) {
 const [state,action,pending]=useActionState(createReview,{});
 const [selected,setSelected]=useState<string[]>([]);
 const [merchant,setMerchant]=useState('');
 const [category,setCategory]=useState('');
 const [assistance,setAssistance]=useState('');
 const [providerBusy,setProviderBusy]=useState(false);
 const draftRevision=useRef(0);
 const nameOf=(targets:Target[],id:string|null)=>id?targets.find(target=>target.id===id)?.name??'':'';
 const suggestion=(proposal:Pick<OrganizationProposal,'merchantId'|'merchantName'|'categoryId'>)=>[proposal.merchantName??nameOf(merchants,proposal.merchantId),nameOf(categories,proposal.categoryId)];
 const fill=(proposal:Pick<OrganizationProposal,'merchantId'|'merchantName'|'categoryId'>)=>{const [m,c]=suggestion(proposal);setMerchant(m);setCategory(c);};
 const rows=items.filter(item=>selected.includes(item.row.id)).map(({row:{id,version}})=>({id,version}));
 const [merchantValue,merchantName]=choice(merchants,merchant);
 const [categoryValue,categoryName]=choice(categories,category);
 const toggle=(ids:string[],on:boolean)=>{draftRevision.current++;setSelected(on?[...new Set([...selected,...ids])]:selected.filter(id=>!ids.includes(id)));};
 function applySuggestion(proposal:OrganizationProposal){
  const key=JSON.stringify(suggestion(proposal));draftRevision.current++;
  setSelected([...new Set([...selected,...items.filter(item=>JSON.stringify(suggestion(item.proposal))===key).map(item=>item.row.id)])]);
  if(items.some(item=>selected.includes(item.row.id)&&JSON.stringify(suggestion(item.proposal))!==key))setAssistance('Added to your selection. These entries have different suggestions, so choose the category and merchant yourself.');
  else{setAssistance('');fill(proposal);}
 }
 async function requestSuggestions(){
  const requestedRevision=draftRevision.current;
  setProviderBusy(true);setAssistance('');
  try{
   const response=await fetch('/api/money/organization/suggestions',{method:'POST',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(25000),body:JSON.stringify({rows,useProvider:true})});
   const body=await response.json() as {proposals?:OrganizationProposal[];providerStatus?:string;notice?:string};
   if(draftRevision.current!==requestedRevision){setAssistance('Your draft changed while suggestions were requested. Keep your choices or ask again.');return;}
   if(!response.ok||body.providerStatus!=='available'){setAssistance(body.notice??'AI suggestions are unavailable right now.');return;}
   const candidates=(body.proposals??[]).filter(candidate=>selected.includes(candidate.transactionId)&&candidate.basis==='provider-suggestion');
   const choices=new Set(candidates.map(candidate=>JSON.stringify([candidate.merchantId,candidate.merchantName,candidate.categoryId])));
   if(candidates.length&&candidates.length===selected.length&&choices.size===1){fill(candidates[0]);setAssistance('Filled from an AI suggestion. Check it in the preview before approving.');}
   else setAssistance(candidates.length?'AI suggestions differ across the selection. Select fewer entries.':'No AI suggestions were returned.');
  }catch{setAssistance('AI suggestions are unavailable right now.');}
  finally{setProviderBusy(false);}
 }
 const chosen=items.filter(item=>selected.includes(item.row.id));
 const keys=new Set(chosen.map(item=>item.proposal.descriptionKey));
 const ruleKey=keys.size===1&&[...keys][0].length>=3?[...keys][0]:null;
 const unchecked=chosen.filter(item=>item.proposal.financialReviewRequired).length;
 const similarCount=(proposal:OrganizationProposal)=>{const key=JSON.stringify(suggestion(proposal));return items.filter(item=>JSON.stringify(suggestion(item.proposal))===key).length;};
 const selectAll=useRef<HTMLInputElement>(null);
 useEffect(()=>{if(selectAll.current)selectAll.current.indeterminate=selected.length>0&&selected.length<items.length;},[selected.length,items.length]);
 const noTarget=merchantValue==='keep'&&categoryValue==='keep';
 const created=[categoryName&&`category “${categoryName}”`,merchantName&&`merchant “${merchantName}”`].filter(Boolean).join(' and ');
 return <form action={action} className="rounded-xl border border-border bg-card">
  <input type="hidden" name="rows" value={JSON.stringify(rows)} />
  <input type="hidden" name="requestId" value={requestId} />
  <input type="hidden" name="merchant" value={merchantValue} /><input type="hidden" name="merchantName" value={merchantName} />
  <input type="hidden" name="category" value={categoryValue} /><input type="hidden" name="categoryName" value={categoryName} />
  <div id="organize-controls" className="flex scroll-mt-24 flex-wrap items-end gap-3 border-b border-border p-4">
   <label className="flex min-h-10 items-center gap-2 text-sm"><input ref={selectAll} type="checkbox" checked={items.length>0&&selected.length===items.length} onChange={event=>toggle(items.map(item=>item.row.id),event.target.checked)} />{selected.length?`${selected.length} selected`:'Select all'}</label>
   <label className="grid gap-1 text-xs text-muted-foreground">Category<input name="categorySearch" list="organize-categories" value={category} onChange={event=>{draftRevision.current++;setCategory(event.target.value);}} maxLength={100} placeholder="Keep current, or type a name" className={field} /></label>
   <label className="grid gap-1 text-xs text-muted-foreground">Merchant<input name="merchantSearch" list="organize-merchants" value={merchant} onChange={event=>{draftRevision.current++;setMerchant(event.target.value);}} maxLength={100} placeholder="Keep current, or type a name" className={field} /></label>
   <datalist id="organize-categories">{categories.map(target=><option key={target.id} value={target.name} />)}</datalist>
   <datalist id="organize-merchants">{merchants.map(target=><option key={target.id} value={target.name} />)}</datalist>
   <button disabled={pending||providerBusy||!rows.length||noTarget} className="min-h-10 rounded-lg bg-brand px-4 py-2 text-sm font-medium text-white disabled:opacity-40">{pending?'Applying…':rows.length?`Apply to ${rows.length}`:'Apply'}</button>
   <label className={'flex min-h-10 items-center gap-2 text-sm'+(ruleKey?'':' text-muted-foreground')}><input type="checkbox" name="saveRule" value="true" disabled={!ruleKey} />{ruleKey?'Suggest the same for future entries like “'+ruleKey+'”':'Suggest the same for future entries (needs one description selected)'}</label>
   <button type="button" disabled={providerBusy||pending||!rows.length} onClick={requestSuggestions} className="min-h-10 text-sm text-muted-foreground underline disabled:opacity-40">{providerBusy?'Asking AI…':'Suggest with AI'}</button>
   {created&&<p className="basis-full text-xs text-muted-foreground">New {created} will be created. Capital letters don’t matter when matching an existing name.</p>}
   {unchecked>0&&<p className="basis-full text-xs text-warning">{unchecked} selected still {unchecked===1?'needs its':'need their'} amount checked. A category doesn’t confirm the amount.</p>}
   {assistance&&<p role="status" className="basis-full text-sm">{assistance}</p>}
   {state.error&&<p role="alert" className="basis-full text-sm text-danger">{state.error}{state.reviewId&&<> <a className="underline" href={'/money/organization?review='+state.reviewId}>Open the saved review</a></>}</p>}
   <p role="status" className="sr-only">{selected.length} selected</p>
  </div>
  <ul className="divide-y divide-border">{groupedByDescription(items).map(group=><Fragment key={group[0].row.id}>
   {group.length>1&&<li className="flex flex-wrap items-center gap-x-3 gap-y-1 bg-muted/40 px-4 py-2.5 text-sm"><label className="flex min-h-10 min-w-0 items-center gap-3 font-medium"><input type="checkbox" checked={group.every(({row})=>selected.includes(row.id))} onChange={event=>toggle(group.map(({row})=>row.id),event.target.checked)} /><span className="min-w-0 break-words">{group[0].row.description}: all {group.length}</span></label><span className="font-mono text-xs text-muted-foreground">{group.at(-1)!.row.posted_on} to {group[0].row.posted_on}</span></li>}
   {group.map(({row,proposal})=>{const hint=suggestion(proposal).filter(Boolean).join(' · ');
   return <li key={row.id} className="flex items-start gap-3 px-4 py-3 text-sm">
    <label className="-m-2 flex size-10 shrink-0 items-center justify-center"><input type="checkbox" aria-label={'Select '+row.description+', '+row.posted_on+', '+formatMoney(row.amount_minor,row.currency_code,locale)} checked={selected.includes(row.id)} onChange={event=>toggle([row.id],event.target.checked)} /></label>
    <div className="min-w-0 flex-1 space-y-1">
     <a className="block break-words hover:underline" href={'/money/transactions?transaction='+row.id}>{row.description}</a>
     <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
      <span className="font-mono text-xs text-muted-foreground">{row.posted_on}</span>
      {proposal.financialReviewRequired&&<a className="text-xs text-muted-foreground underline" href={'/money/transactions?transaction='+row.id}>Review its amount first</a>}
      {hint&&<button type="button" onClick={()=>applySuggestion(proposal)} className="min-h-8 rounded-full border border-border px-2.5 py-1 text-xs text-muted-foreground hover:text-foreground">Select {similarCount(proposal)} like this: {hint}</button>}
     </div>
    </div>
    <span className="shrink-0 whitespace-nowrap font-mono">{formatMoney(row.amount_minor,row.currency_code,locale)}</span>
   </li>;})}</Fragment>)}</ul>
  {rows.length>0&&<div className="sticky bottom-20 z-10 max-lg:bottom-[calc(4rem+env(safe-area-inset-bottom))] flex flex-wrap items-center gap-3 rounded-b-xl border-t border-border bg-card p-3 shadow-lg md:bottom-4">
   <p className="text-sm font-medium">{rows.length} selected</p>
   {noTarget?<a className="text-sm underline" href="#organize-controls">Choose a category or merchant</a>:<p className="min-w-0 flex-1 truncate text-sm text-muted-foreground">{[category,merchant].filter(Boolean).join(' · ')}</p>}
   <button disabled={pending||providerBusy||noTarget} className="ml-auto min-h-10 rounded-lg bg-brand px-4 py-2 text-sm font-medium text-white disabled:opacity-40">{pending?'Applying…':'Apply'}</button>
  </div>}
 </form>;
}
export function ApprovalForm({reviewId,canSaveRule}:{reviewId:string;canSaveRule:boolean}) {
 const [state,action,pending]=useActionState(applyReview,{});
 return <form action={action} className="mt-4 space-y-3">
  <input type="hidden" name="reviewId" value={reviewId} />
  <input type="hidden" name="confirmed" value="true" />
  {canSaveRule&&<label className="flex gap-2 text-sm"><input type="checkbox" name="saveRule" value="true" />Suggest the same for future entries with this description.</label>}
  {state.error&&<p role="alert" className="text-sm text-danger">{state.error}</p>}
  <button disabled={pending} className="min-h-10 rounded-lg bg-brand px-4 py-2 text-sm font-medium text-white disabled:opacity-40">{pending?'Applying…':'Apply'}</button>
 </form>;
}
export function UndoReviewForm({reviewId,rows}:{reviewId:string;rows:{id:string;version:number}[]}) {
