88	   {group.length>1&&<li className="flex flex-wrap items-center gap-x-3 gap-y-1 bg-muted/40 px-4 py-2.5 text-sm"><label className="flex min-h-10 min-w-0 items-center gap-3 font-medium"><input type="checkbox" checked={group.every(({row})=>selected.includes(row.id))} onChange={event=>toggle(group.map(({row})=>row.id),event.target.checked)} /><span className="min-w-0 break-words">{group[0].row.description}: all {group.length}</span></label><span className="font-mono text-xs text-muted-foreground">{group.at(-1)!.row.posted_on} to {group[0].row.posted_on}</span></li>}
