113	  <input type="hidden" name="confirmed" value="true" />
114	  {canSaveRule&&<label className="flex gap-2 text-sm"><input type="checkbox" name="saveRule" value="true" />Suggest the same for future entries with this description.</label>}
115	  {state.error&&<p role="alert" className="text-sm text-danger">{state.error}</p>}
116	  <button disabled={pending} className="min-h-10 rounded-lg bg-brand px-4 py-2 text-sm font-medium text-white disabled:opacity-40">{pending?'Applying…':'Apply'}</button>
117	 </form>;
118	}
