120	 const [state,action,pending]=useActionState(undoReview,{});
121	 return <form action={action} className="mt-3"><input type="hidden" name="reviewId" value={reviewId} /><input type="hidden" name="rows" value={JSON.stringify(rows)} />
122	  {state.error&&<p role="alert" className="mb-2 text-sm text-danger">{state.error}</p>}
123	  <button disabled={pending} className="text-sm underline disabled:opacity-40">{pending?'Undoing…':'Undo this batch'}</button>
124	 </form>;
125	}
