import type { SupabaseClient } from "@supabase/supabase-js";
import { loadLoanPayoutIds } from "@/lib/finance/iou";
import { cardTransactions, type CardTransaction } from "@/lib/ai/open-proposals";

export type HomeFinding = { ids: string[]; title: string; detail: string; href: string | null; transactions: CardTransaction[] };
export type HomeReview = { uncategorized: number; findings: HomeFinding[] };

type FindingRow = { id: string; conflict_key: string; title: string; detail: string; evidence: { links?: { href: string }[]; transactions?: { id: string }[] } | null };

export async function loadHomeReview(supabase: SupabaseClient, workspaceId: string): Promise<HomeReview> {
  const loans = await loadLoanPayoutIds(supabase, workspaceId).catch(() => new Set<string>());
  let count = supabase.from("transactions").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "posted").is("category_id", null).neq("kind", "transfer");
  if (loans.size) count = count.not("id", "in", `(${[...loans].join(",")})`);
  const [uncategorized, findings] = await Promise.all([
    count,
    supabase.from("agent_proposals").select("id, conflict_key, title, detail, evidence").eq("workspace_id", workspaceId).eq("kind", "finding").eq("status", "proposed")
      .not("run_id", "is", null).order("created_at", { ascending: false }).limit(300),
  ]);
  if (uncategorized.error) throw new Error(uncategorized.error.message);
  if (findings.error) throw new Error(findings.error.message);
  const byKey = new Map<string, HomeFinding>();
  for (const row of (findings.data ?? []) as FindingRow[]) {
    if (row.evidence?.transactions?.length && row.evidence.transactions.every(item => loans.has(item.id))) continue;
    const known = byKey.get(row.conflict_key);
    if (known) { known.ids.push(row.id); continue; }
    const transaction = row.evidence?.transactions?.[0]?.id;
    byKey.set(row.conflict_key, { ids: [row.id], title: row.title, detail: row.detail, transactions: cardTransactions(row.evidence),
      href: transaction ? `/money/transactions?transaction=${transaction}` : row.evidence?.links?.[0]?.href ?? null });
  }
  return { uncategorized: uncategorized.count ?? 0, findings: [...byKey.values()] };
}
import type {SupabaseClient} from '@supabase/supabase-js';
import {z} from 'zod';
import {versionedRows} from '@/lib/finance/transaction-input';
import {MAX_ORGANIZATION_RULES,organizationProposals,organizationRuleSchema,type OrganizationRow} from '@/lib/import/organization';

const columns='id,version,description,merchant_id,category_id,kind,review_reasons,posted_on,amount_minor::text,currency_code,status,organized_by';
export async function loadOrganizationSuggestions(db:SupabaseClient,workspaceId:string,selection:unknown) {
 z.uuid().parse(workspaceId);const selected=versionedRows.parse(selection),ids=selected.map(row=>row.id);
 const [current,history,corrections,rules]=await Promise.all([
  db.from('transactions').select(columns).eq('workspace_id',workspaceId).neq('status','voided').in('id',ids),
  db.from('transactions').select(columns).eq('workspace_id',workspaceId).eq('status','posted').order('posted_on',{ascending:false}).order('id',{ascending:false}).limit(2000),
  db.from('correction_events').select('transaction_id,origin').eq('workspace_id',workspaceId).eq('undone',false).in('transaction_id',ids),
  db.from('organization_rules').select('id,version,description_key,merchant_id,category_id,approved_by,enabled').eq('workspace_id',workspaceId).order('description_key').limit(MAX_ORGANIZATION_RULES),
 ]);
 if(current.error||history.error||corrections.error||rules.error)throw current.error??history.error??corrections.error??rules.error;
 const byId=new Map(current.data.map(row=>[row.id,row]));
 if(byId.size!==selected.length||current.data.length!==byId.size||selected.some(row=>byId.get(row.id)?.version!==row.version))throw new Error('The selected history changed; reload suggestions');
 const corrected=new Set(corrections.data.filter(event=>event.origin!=='ai').map(event=>event.transaction_id));
 const toRow=(row:typeof current.data[number]):OrganizationRow=>({id:row.id,version:row.version,description:row.description,
  merchantId:row.merchant_id,categoryId:row.category_id,kind:row.kind,reviewReasons:row.review_reasons,userCorrected:corrected.has(row.id)});
 const approved=rules.data.map(rule=>organizationRuleSchema.parse({id:rule.id,version:rule.version,descriptionKey:rule.description_key,
  merchantId:rule.merchant_id,categoryId:rule.category_id,approvedBy:rule.approved_by,enabled:rule.enabled}));
 return {rows:selected.map(row=>byId.get(row.id)!),proposals:organizationProposals(current.data.map(toRow),history.data.filter(row=>row.organized_by!=='ai').map(toRow),approved),historyLimit:2000,historyCount:history.data.length};
}
