import postgres from "postgres";
process.loadEnvFile(".env.qa");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const users = await db`select id from auth.users where raw_user_meta_data->>'qa_test'='home-categorize'`;
for (const { id } of users) await db.begin(async tx => {
  await tx`select set_config('request.jwt.claim.sub', ${id}, true)`;
  await tx`select public.reset_workspace()`;
  await tx`delete from public.workspace_settings where workspace_id in (select id from public.workspaces where owner_id = ${id})`;
  await tx`delete from public.categories where workspace_id in (select id from public.workspaces where owner_id = ${id})`;
  await tx`delete from public.workspaces where owner_id = ${id}`;
  await tx`delete from auth.users where id = ${id}`;
});
console.log("removed", users.length);
await db.end();
EOF
